import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.Ca9F9Y59.js";const o="/k3gdb/assets/TOD_%E5%9B%9B%E9%98%B6%E6%AE%B5.L6Jqi_OC.png",l="/k3gdb/assets/TOD_%E4%B8%89%E5%A4%A7%E9%97%AE%E9%A2%98.De1tAumu.png",s="/k3gdb/assets/RR_%E7%BA%B5%E5%90%91%E5%88%86%E5%B1%82%E6%9E%B6%E6%9E%84.CTQnmyvg.png",n="/k3gdb/assets/RR_%E4%B8%89%E9%A1%B9%E6%9C%BA%E5%88%B6%E4%B8%8E%E7%BC%93%E5%86%B2%E4%BC%98%E5%8C%96.DqGGHrid.png",p="/k3gdb/assets/ARD_%E6%9E%B6%E6%9E%84%E5%AF%B9%E7%85%A7.DRxzT6hb.png",D=JSON.parse('{"title":"ARD调试K3工作","description":"","frontmatter":{},"headers":[],"relativePath":"2026-10-15-StarryOS_N部署与ARD真板验证阶段日志.md","filePath":"2026-10-15-StarryOS_N部署与ARD真板验证阶段日志.md"}'),h={name:"2026-10-15-StarryOS_N部署与ARD真板验证阶段日志.md"};function d(c,a,u,_,g,b){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="ard调试k3工作" tabindex="-1">ARD调试K3工作 <a class="header-anchor" href="#ard调试k3工作" aria-label="Permalink to &quot;ARD调试K3工作&quot;">​</a></h1><h2 id="_1-starryos-启动性能优化" tabindex="-1">1. StarryOS 启动性能优化 <a class="header-anchor" href="#_1-starryos-启动性能优化" aria-label="Permalink to &quot;1. StarryOS 启动性能优化&quot;">​</a></h2><p>问题：原Starryos启动调试时间消耗太大。</p><p>最初使用的 StarryOS 实验环境启动耗时较长，从 Welcome 到进入 Shell 平均需要约 264 秒，完整启动时间约300秒</p><p>为解决这一问题，更换为经过改造的新starryOS分支建立独立工作区，重新编译包含 DWARF 调试信息的 ELF，并适配 K3 原有固件和 UFS 启动流程。github链接：<a href="https://github.com/Oveln/tgoskits/tree/feat/k3-board-support" target="_blank" rel="noreferrer">https://github.com/Oveln/tgoskits/tree/feat/k3-board-support</a></p><p>经过六轮测试，新版本从 Welcome 到 Shell 的中位耗时缩短至 <strong>21.50 秒</strong>，相比原派生实验镜像减少约 <strong>242.84 秒（91.87%）</strong>，该阶段启动速度提升约 <strong>12.29 倍</strong>。正式工作区重新编译后的镜像也完成了真板启动验证，耗时约 21.51 秒。</p><h2 id="_2-ard-真板调试验证" tabindex="-1">2. ARD 真板调试验证 <a class="header-anchor" href="#_2-ard-真板调试验证" aria-label="Permalink to &quot;2. ARD 真板调试验证&quot;">​</a></h2><p>在新的 StarryOS 环境下，成功完成 OpenOCD、GDB 和 ARD Debug Adapter 连接，Rust 源码断点能够正常命中。</p><p>同时验证了 ARD 的 RuntimeEvent、History、Observer Tree 和 Snapshot 功能，成功观察到 <code>sleep_until → TimerFuture::poll</code> 异步运行关系。</p><p>改进后显著减少了进入 Shell 前的等待时间与 ARD 调试时间。将 ARD 原有的测试示例改为新测试用例，同时完成了测试配置、工作区校验器和相关文档更新，支持通过环境变量指定外部 StarryOS 工作区。</p><h1 id="《back-to-the-future-omniscient-debugging》-全知调试" tabindex="-1">《Back to the Future: Omniscient Debugging》-全知调试 <a class="header-anchor" href="#《back-to-the-future-omniscient-debugging》-全知调试" aria-label="Permalink to &quot;《Back to the Future: Omniscient Debugging》-全知调试&quot;">​</a></h1><h2 id="_1-问题" tabindex="-1">1. 问题 <a class="header-anchor" href="#_1-问题" aria-label="Permalink to &quot;1. 问题&quot;">​</a></h2><p>Bug产生的原因通常在程序出现异常之前 原来程序调试方法有两种:</p><h3 id="日志调试" tabindex="-1">日志调试 <a class="header-anchor" href="#日志调试" aria-label="Permalink to &quot;日志调试&quot;">​</a></h3><p>通过提前插入日志记录程序运行过程。</p><p>它可以保留程序历史执行信息。</p><p>但是需要提前修改代码。并且日志输出信息太多，后续人工分析困难。</p><h3 id="断点调试" tabindex="-1">断点调试 <a class="header-anchor" href="#断点调试" aria-label="Permalink to &quot;断点调试&quot;">​</a></h3><p>如 GDB，通过暂停程序详细观察当前状态。</p><p>但是它只能看到当前执行位置，对于之前发生了什么通常无法恢复。开发人员需要不断重新运行程序，通过调整断点逐渐缩小范围。</p><p>怎样让开发者能够高效的回到过去，找到导致当前错误的事件？</p><h2 id="_2-提出方法" tabindex="-1">2. 提出方法 <a class="header-anchor" href="#_2-提出方法" aria-label="Permalink to &quot;2. 提出方法&quot;">​</a></h2><p>论文提出 <strong>Omniscient Debugging（全知调试）</strong>，核心思想是：</p><blockquote><p>记录程序完整执行历史，并允许开发者像查看录像一样，在执行历史中前后导航。</p></blockquote><p>它结合了两种调试方式的特点：</p><ul><li><strong>日志调试</strong>：保存过去发生的事情；</li><li><strong>断点调试</strong>：交互查看程序状态。</li></ul><p>因此可以支持：</p><ul><li>向前执行；</li><li>向后回溯；</li><li>根据因果关系寻找错误来源。</li></ul><h2 id="_3-系统实现-tod" tabindex="-1">3. 系统实现：TOD <a class="header-anchor" href="#_3-系统实现-tod" aria-label="Permalink to &quot;3. 系统实现：TOD&quot;">​</a></h2><p>作者实现了一个 Java 全知调试器：<strong>Trace-Oriented Debugger（TOD）</strong>。</p><p>核心目标：查询和导航历史事件 <img src="'+o+'" alt="TOD四阶段"></p><h2 id="_4-论文解决的关键问题" tabindex="-1">4. 论文解决的关键问题 <a class="header-anchor" href="#_4-论文解决的关键问题" aria-label="Permalink to &quot;4. 论文解决的关键问题&quot;">​</a></h2><p>全知调试主要面临三个挑战，作者对此进行了解决。</p><p><img src="'+l+'" alt="TOD四阶段"></p><h1 id="《lightweight-user-space-record-and-replay》-调试的记录与重播" tabindex="-1">《Lightweight User-Space Record And Replay》-调试的记录与重播 <a class="header-anchor" href="#《lightweight-user-space-record-and-replay》-调试的记录与重播" aria-label="Permalink to &quot;《Lightweight User-Space Record And Replay》-调试的记录与重播&quot;">​</a></h1><h2 id="_1-问题-1" tabindex="-1">1. 问题 <a class="header-anchor" href="#_1-问题-1" aria-label="Permalink to &quot;1. 问题&quot;">​</a></h2><p>在程序调试过程中，有些 Bug 很难稳定复现，比如多线程竞争、异步信号或偶发错误。传统 GDB 调试通常需要反复运行程序，但每次执行过程可能不一样，因此很难准确找到错误原因。</p><h3 id="分析" tabindex="-1">分析 <a class="header-anchor" href="#分析" aria-label="Permalink to &quot;分析&quot;">​</a></h3><p>方案1：通过整个虚拟机记录，但是记录信息太多，过于笨重</p><p>方案2：修改内核，会导致部署困难，普通用户不能直接使用。</p><p>方案3：代码插桩，需要修改/监控大量代码，导致性能下降</p><h2 id="_2-提出方法-1" tabindex="-1">2. 提出方法 <a class="header-anchor" href="#_2-提出方法-1" aria-label="Permalink to &quot;2. 提出方法&quot;">​</a></h2><p>作者认为，CPU 执行的大部分普通计算是确定性的，但是以下事情可能不同：</p><ul><li>系统调用返回的数据；</li><li>多线程执行顺序；</li><li>信号在什么位置到达；</li><li>某些非确定性 CPU 指令的结果。</li></ul><p>因此rr 选择用户空间与 Linux 内核之间的接口作为主要记录边界，通过控制不确定的变量，追求准确的记录并回放程序。 <img src="'+s+'" alt="RR 架构"></p><p>为了应对几个关键问题，系统主要采用三个技术机制。</p><p><img src="'+n+'" alt="RR 三项机制"></p><h1 id="ard调试器与async-debug调试器架构区分" tabindex="-1">ARD调试器与async-debug调试器架构区分 <a class="header-anchor" href="#ard调试器与async-debug调试器架构区分" aria-label="Permalink to &quot;ARD调试器与async-debug调试器架构区分&quot;">​</a></h1><p>真正的区别主要在信息如何采集、保存、验证以及最终展示</p><ul><li>旧版研究如何观察并恢复异步执行路径的问题；</li><li>新版进一步研究如何持续的保留运行历史和建立关系，从而对历史与当前状态展示的问题。</li></ul><p>主要架构如下： <img src="'+p+'" alt="架构对比"></p><p>由于异步函数在执行过程中调用栈不连续。并且存在一个函数多次poll不同函数的情况</p><ul><li>快照累计版本能够观察到某些函数的执行，但是完整调用链依赖停止点 Snapshot 累计，未能将其保留在调用树中；</li><li>新版通过后端运行事件积累，可以在没有中途 Snapshot 的情况下保留相应执行信息 下一步实验方向：验证旧版快照累计是否遗漏已观测的异步执行信息，以及新版后端 History 能否有效保留这些历史。</li></ul>',53)])])}const E=e(h,[["render",d]]);export{D as __pageData,E as default};
